// ===== Cấu hình chung cấp 1 (sửa ở đây) =====
const CFG = {
  SHEET_ID: '1k7Jl7EzZPI7O0t8Mjfkko4gu_7aWymzfNdjFMXVrnu0',
  TOKEN: 'DOI_TOKEN_O_DAY',                 // trùng biến SMOCK_LOG_TOKEN trên máy cấp 3
  PACK_DIR: 'C:/claude remote/anh-dang-bai', // thư mục gói bài cấp 3 đọc
  L2_REPO: 'C:/smock-level2-copilot',        // bản clone repo cấp 2 trên máy này
  // Giờ làm việc theo THỊ TRƯỜNG (người dùng chốt 22/11/2026, máy treo 24/24, chạy cả tuần): khung giờ ghi theo giờ địa phương
  // của thị trường, tự quy đổi sang giờ VN theo ngày (tự đổi khi Mỹ/Anh vào giờ mùa hè). Khách chính: boutique/shop online US, sau đó UK/EU.
  MARKET_WINDOWS: [
    { name: 'US tối', tz: 'America/New_York', from: '19:00', to: '21:45' },    // = VN 07:00–09:45 (mùa đông) / 06:00–08:45 (mùa hè)
    { name: 'UK/EU sáng', tz: 'Europe/London', from: '08:00', to: '10:30' },  // = VN 15:00–17:30 / 14:00–16:30 (cũng là tối ở Úc)
    { name: 'US sáng', tz: 'America/New_York', from: '08:00', to: '11:30' },   // = VN 20:00–23:30 / 19:00–22:30
  ],
  NICK_GROUP_GAP_MIN: 60,       // 2 bài group của CÙNG 1 nick cách nhau tối thiểu (phút)
  TEAM_GROUP_GAP_MIN: 6,        // 2 bài group bất kỳ của cả đội cách nhau tối thiểu (phút)
  GROUP_REPOST_DAYS: 3,         // 1 nick không đăng lại cùng 1 group trong ngần này ngày; cả đội không trùng group trong ngày
  TASK_GAP: [2, 4], BLOCK_GAP: [6, 12], // phút giữa 2 việc trong cụm / giữa 2 cụm
  LANES: 2,                     // số luồng chạy song song: mỗi luồng = 1 phiên Claude cấp 3 + nhóm trình duyệt riêng
  JG_COL: { SM01: 3, SM02: 4, SM03: 5, SM04: 8, SM05: 9, SM06: 10, SM07: 11, SM08: 12 }, // cột nick trong tab Join Group SM (D,E,F,I..M)
  JG_TIER_COL: 6,               // cột G "Tier" tab Join Group SM — dùng khi tab Group Score chưa chấm
  K_START: 122,                 // mã bài Kxxx lớn nhất đã dùng trước khi có n8n (Smock Radar)
  CONTENT_REUSE_DAYS: 7,        // bộ ảnh được phái sinh caption mới sau ngần này ngày
  // ---- Trần cứng chống spam (chế độ nào cũng không vượt) ----
  MAX_GROUP_PER_NICK: 5,        // bài group/nick/ngày tối đa, dù cột G tab Target ghi cao hơn
  MAX_WALL_PER_NICK: 3,         // bài tường/nick/ngày tối đa (lưới an toàn nếu cột D gõ nhầm)
  GROUP_RAMP_START: '',         // vd '2026-11-23' = tuần 1 của lộ trình 3→4→5; để trống = chỉ theo cột G (≤ MAX_GROUP_PER_NICK)
  GROUP_RAMP: [3, 4, 5],        // trần bài group/nick theo tuần thứ 1, 2, 3+ kể từ GROUP_RAMP_START
  // ---- Kiểm tồn kho content (L1-02 xếp bài, L1-06 gửi việc cấp 2, L1-04 báo cáo) ----
  STOCK_FULL_DAYS: 7,           // tồn > ngần này ngày → "Đầy": lấp đủ slot, ưu tiên content gốc cũ/đúng mùa, giảm phái sinh
  STOCK_LOW_DAYS: 2,            // tồn < ngần này ngày → "Ít": vẫn bình thường, đẩy mạnh phái sinh cấp 2, báo ở L1-04
  // 18/11 người dùng chốt: CHỈ dùng caption gốc KE, không phái sinh, không ghi mã Kxxx lên caption, WhatsApp = số dưới.
  USE_POOL_DERIVED: false,      // false = bỏ caption phái sinh (tab Pool Content SM) khỏi kho
  WHATSAPP: '+84 855 555 490',  // số WhatsApp chung SM01–SM03: thay mọi số điện thoại trong caption gốc KE
  L2_CAPTION_JOBS: { 'Đầy': 0, 'Vừa': 0, 'Ít': 0 },    // số việc phái sinh caption L1-06 gửi mỗi lượt (0 = tắt phái sinh)
  RECLAIM_UNPOSTED: true,       // content đã xếp lịch nhưng KHÔNG đăng (H ≠ Done, I trống, Nhật Ký không có) → trả lại kho để xếp bù
  RECLAIM_AFTER_DAYS: 2,        // chỉ lấy lại dòng lịch cũ hơn ngày đích ngần này ngày (chờ log/webhook trễ, tránh đăng trùng)
  PERSONA_IN_POOL: false,       // caption persona GRACIE/CATHIE/LILY/EMILY: chưa có node đọc → chưa tính vào kho
  // Chế độ "Đầy": ưu tiên caption có từ khoá đúng mùa theo THÁNG của ngày đích (cuối năm khách làm collection đầu năm + hè)
  SEASON: {
    11: "valentine|st\\.? ?patrick|easter|mother'?s day|summer|spring",
    12: "valentine|st\\.? ?patrick|easter|mother'?s day|summer|spring",
    1: "st\\.? ?patrick|easter|mother'?s day|summer|spring",
    2: "easter|mother'?s day|summer|spring|4th of july",
    3: "mother'?s day|summer|4th of july|back to school",
  },
};
// Kho content dùng tab có sẵn, KHÔNG cần tab riêng:
//  - workbook KE, tab '3. CONTENT GROUP' (A STT, B TEXT, C MEDIA) → mã CG<STT>
//  - tab 'Pool Content SM' (A STT, B Content, C Ảnh/Video, D Phân loại) → mã PC<STT>; Phân loại có "chờ duyệt" thì chưa dùng
//  - content đã dùng / mã bài Kxxx: đọc từ cột F, J tab 'Lịch SM' (vd "đăng group K123 (CG13) → group 5")
const buildPool = (ke, pool) => {
  const out = [];
  // row = số dòng thật trên sheet (KE đọc từ A3, Pool Content SM đọc từ A2)
  ke.forEach((r, i) => { const s = String(r[0] || '').trim(); if (/^\d+$/.test(s) && String(r[1] || '').trim()) out.push({ id: 'CG' + s, caption: r[1], media: r[2] || '', kind: 'any', row: i + 3 }); });
  if (CFG.USE_POOL_DERIVED) pool.forEach((r, i) => { const s = String(r[0] || '').trim(); if (/^\d+$/.test(s) && String(r[1] || '').trim() && !/chờ duyệt/i.test(r[3] || ''))
    out.push({ id: 'PC' + s, caption: r[1], media: r[2] || '', kind: /tường|wall/i.test(r[3] || '') ? 'wall' : 'any', note: r[3] || '', row: i + 2 }); });
  return out;
};
const lichText = r => (r[5] || '') + ' ' + (r[9] || '');
const usedContent = lich => { const s = new Set(); for (const r of lich) for (const m of lichText(r).matchAll(/\b(CG|PC)(\d+)\b/g)) s.add(m[1] + m[2]); return s; };
const maxKOf = (lich, start) => { let k = start; for (const r of lich) for (const m of lichText(r).matchAll(/\bK(\d{3,})\b/g)) k = Math.max(k, +m[1]); return k; };
const vnNow = () => new Date(new Date().toLocaleString('en-US', { timeZone: 'Asia/Ho_Chi_Minh' }));
const isoOf = d => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
const vnOf = d => `${d.getDate()}/${d.getMonth() + 1}/${d.getFullYear()}`;
const sameDay = (s, d) => { s = String(s || '').trim(); return s.startsWith(isoOf(d)) || s.startsWith(vnOf(d)); };
const pDay = s => { s = String(s || ''); let m = /^(\d{4})-(\d{2})-(\d{2})/.exec(s); if (m) return new Date(+m[1], +m[2] - 1, +m[3]);
  m = /^(\d{1,2})\/(\d{1,2})\/(\d{4})/.exec(s); return m ? new Date(+m[3], +m[2] - 1, +m[1]) : null; };
// Ngày đích: chạy sáng (trước 12h) → hôm nay; chiều/tối → ngày kế tiếp. Từ 22/11/2026 chạy cả 7 ngày (máy treo 24/24).
const targetDayOf = now => { const d = new Date(now); if (now.getHours() >= 12) d.setDate(d.getDate() + 1); return d; };
// Lệch giờ (phút) của múi giờ tz so với UTC tại thời điểm dt
const tzOff = (tz, dt) => { const p = {}; for (const x of new Intl.DateTimeFormat('en-US', { timeZone: tz, hourCycle: 'h23', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' }).formatToParts(dt)) p[x.type] = x.value;
  return Math.round((Date.UTC(+p.year, +p.month - 1, +p.day, +p.hour % 24, +p.minute) - dt.getTime()) / 60000); };
// Khung giờ thị trường quy ra phút trong ngày VN của ngày d: [[bắt đầu, kết thúc, tên], ...] tăng dần
const windowsVN = d => { const noon = new Date(Date.UTC(d.getFullYear(), d.getMonth(), d.getDate(), 5, 0)); // 12:00 VN
  const m = s => +s.slice(0, 2) * 60 + +s.slice(3);
  return CFG.MARKET_WINDOWS.map(w => { const sh = 420 - tzOff(w.tz, noon); const a = ((m(w.from) + sh) % 1440 + 1440) % 1440; let b = ((m(w.to) + sh) % 1440 + 1440) % 1440; if (b < a) b = 1439; return [a, b, w.name]; })
    .sort((x, y) => x[0] - y[0]); };
// Trần bài group/nick theo lộ trình tuần (GROUP_RAMP_START trống = không giới hạn thêm)
const rampCap = d => { const s = pDay(CFG.GROUP_RAMP_START); if (!s) return Infinity;
  const w = Math.max(0, Math.floor((new Date(d.getFullYear(), d.getMonth(), d.getDate()) - s) / (7 * 864e5))); return CFG.GROUP_RAMP[Math.min(w, CFG.GROUP_RAMP.length - 1)]; };
const isNoGroup = st => /hạn chế group|không group|no group/i.test(st || '');
// Số bài cần mỗi ngày theo KPI hiện tại (tab Target + Workload), đã áp trần cứng; nick không "Hoạt động" không tính
const dailyNeed = (acc, kpi, d) => { const q = {}; for (const r of kpi) if (/^SM0\d$/.test(r[0])) q[r[0]] = r; let n = 0;
  for (const a of acc) { if (!/^SM0\d$/.test(a[0]) || !/Hoạt động/i.test(a[5] || '')) continue; const r = q[a[0]];
    n += r ? Math.min(+r[3] || 0, CFG.MAX_WALL_PER_NICK) : 1;
    if (r && !isNoGroup(a[5])) n += Math.min(+r[6] || 0, CFG.MAX_GROUP_PER_NICK, rampCap(d)); }
  return n; };
// Content có ảnh = có link Drive (folder / file). Thiếu link → không đăng được, không tính tồn
const hasImg = x => /drive\.google\.com|\/folders\/[\w-]+|[?&]id=[\w-]+|\/d\/[\w-]+/.test(String(x.media || ''));
// Kiểm tồn kho: content chưa dùng có ảnh / số bài cần mỗi ngày → chế độ Đầy / Vừa / Ít
//  - đã đăng: dòng Lịch SM có H Done/Đang làm hoặc có URL (cột I), hoặc Nhật Ký SM "Đăng bài" Xong có mã Kxxx/CGn/PCn
//  - đang chờ: dòng lịch chưa đăng nhưng còn mới (≥ ngày đích − RECLAIM_AFTER_DAYS) → giữ chỗ, không xếp lại
//  - lỗi ảnh: L1-03 ghi "Lỗi gói 0/0" (folder không có ảnh) → loại khỏi kho
//  - còn lại (lịch cũ bị bỏ qua/không kịp làm) → trả lại kho, xếp bù
const stockOf = ({ ke, pool, lich, nk, acc, kpi, d }) => {
  const all = buildPool(ke || [], pool || []);
  const day0 = new Date(d.getFullYear(), d.getMonth(), d.getDate());
  const postedNk = new Set();
  for (const r of nk || []) if (r[3] === 'Đăng bài' && /^(Xong|Một phần)$/.test(r[8] || ''))
    for (const m of ((r[4] || '') + ' ' + (r[5] || '')).matchAll(/\b(K\d{3,}|CG\d+|PC\d+)\b/g)) postedNk.add(m[1]);
  const posted = new Set(), pending = new Set(), noImg = new Set(), seen = new Set();
  for (const r of lich || []) {
    const ids = [...lichText(r).matchAll(/\b(CG|PC)(\d+)\b/g)].map(m => m[1] + m[2]); if (!ids.length) continue;
    const k = (/\bK\d{3,}\b/.exec(r[5] || '') || [])[0]; const dd = pDay(r[0]); const st = String(r[7] || '').trim();
    const done = /^(Done|Đang làm|Đã đăng)$/i.test(st) || !!String(r[8] || '').trim() || (k && postedNk.has(k)) || ids.some(i => postedNk.has(i));
    const old = CFG.RECLAIM_UNPOSTED && dd && (day0 - dd) / 864e5 >= CFG.RECLAIM_AFTER_DAYS;
    for (const id of ids) { seen.add(id);
      if (done) posted.add(id); else if (/Lỗi gói 0\/0/.test(r[9] || '')) noImg.add(id); else if (!old) pending.add(id); }
  }
  const blocked = id => posted.has(id) || pending.has(id) || noImg.has(id);
  let list = all.filter(x => !blocked(x.id) && hasImg(x));
  const reclaimed = list.filter(x => seen.has(x.id)).length;
  const need = dailyNeed(acc || [], kpi || [], d);
  const days = need > 0 ? list.length / need : null;
  const mode = days === null ? 'Vừa' : days > CFG.STOCK_FULL_DAYS ? 'Đầy' : days < CFG.STOCK_LOW_DAYS ? 'Ít' : 'Vừa';
  if (mode === 'Đầy') {   // hấp thụ: đúng mùa trước, content gốc KE trước phái sinh, số nhỏ (cũ) trước
    const s = CFG.SEASON[d.getMonth() + 1]; const re = s ? new RegExp(s, 'i') : null;
    const key = x => [re && re.test(x.caption) ? 0 : 1, /^CG/.test(x.id) ? 0 : 1, +x.id.slice(2)];
    list = list.map((x, i) => ({ x, k: key(x), i })).sort((a, b) => a.k[0] - b.k[0] || a.k[1] - b.k[1] || a.k[2] - b.k[2] || a.i - b.i).map(o => o.x);
  }
  const daysTxt = days === null ? '—' : days.toFixed(1).replace('.', ',');
  const missing = all.filter(x => !posted.has(x.id) && (!hasImg(x) || noImg.has(x.id))).length;
  const tag = `kho ${mode} ${daysTxt} ngày (${list.length} bài có ảnh chưa đăng, cần ${need}/ngày` + (reclaimed ? `, ${reclaimed} bài lịch cũ xếp bù` : '')
    + (missing ? `, ${missing} bài thiếu ảnh` : '') + ')';
  return { list, unused: list.length, need, days, mode, reclaimed, missing, tag };
};

// Bài cần gói = dòng Lịch SM từ hôm nay trở đi, lệnh "đăng … Kxxx (CGn|PCn)", cột J chưa ghi "Gói sẵn"
const V = n => { try { return (($(n).first().json) || {}).values || []; } catch (e) { return []; } };
const lich = V('Đọc Lịch SM'); const pool = buildPool(V('Đọc content KE'), V('Đọc Pool Content SM'));
const byId = Object.fromEntries(pool.map(x => [x.id, x]));
const today = vnNow(); today.setHours(0, 0, 0, 0);
const parseDay = s => { s = String(s || ''); let m = /^(\d{4})-(\d{2})-(\d{2})/.exec(s); if (m) return new Date(+m[1], +m[2] - 1, +m[3]);
  m = /^(\d{1,2})\/(\d{1,2})\/(\d{4})/.exec(s); return m ? new Date(+m[3], +m[2] - 1, +m[1]) : null; };
const out = [];
lich.forEach((r, i) => {
  const dd = parseDay(r[0]); if (!dd || dd < today || r[7] === 'Done') return;
  const m = /\b(K\d{3,})\b.*?\b((?:CG|PC)\d+)\b/.exec(r[5] || ''); if (!m || /Gói sẵn/.test(r[9] || '')) return;
  const code = m[1], src = byId[m[2]];
  if (!src) { out.push({ json: { row: i + 2, code, note: r[9] || '', missing: m[2] } }); return; }
  const link = src.media || ''; const f = /folders\/([\w-]+)/.exec(link) || /[?&]id=([\w-]+)/.exec(link) || /\/d\/([\w-]+)/.exec(link);
  // Caption = nguyên văn caption gốc KE. KHÔNG ghi mã bài Kxxx (mã chỉ dùng nội bộ: Lịch SM, Radar).
  // Chỉ đổi số điện thoại/WhatsApp trong caption sang CFG.WHATSAPP; bỏ câu chứa {{MA_BAI}} nếu còn sót.
  let cap = String(src.caption)
    .replace(/[^\n]*\{\{MA_BAI\}\}[^\n]*\n?/g, '')
    .replace(/(?:\+\s?84|\b84|\b0)(?:[ .\-]?\d){8,10}\b/g, CFG.WHATSAPP).trim();
  out.push({ json: { row: i + 2, code, src: m[2], note: r[9] || '', caption: cap, folderId: f ? f[1] : null, dir: `${CFG.PACK_DIR}/${code}` } });
});
return out.length ? out : [{ json: { empty: true } }];

const items = [];
for (const it of $('Có bài?').all()) {
  if (it.json.empty) continue;
  items.push({ json: it.json, binary: { data: { data: Buffer.from(it.json.caption, 'utf8').toString('base64'), mimeType: 'text/plain', fileName: 'caption.txt' } } });
}
return items;

// Mỗi bài → danh sách file trong folder (từ Drive API) → mỗi ảnh một item để tải bản JPG 2048px
// Node Drive trả 1 item cho mỗi bài theo đúng thứ tự đầu vào → ghép với bài cùng vị trí ở nhánh "Có bài?"
const out = []; const metas = $('Có bài?').all();
$input.all().forEach((it, k) => {
  const meta = metas[k] ? metas[k].json : {};
  const files = (it.json.files || []).filter(f => /^image\//.test(f.mimeType || '')).sort((a, b) => String(a.name).localeCompare(String(b.name)));
  // Tải qua Drive API: ảnh thường lấy bản gốc (alt=media); HEIC lấy thumbnail 2048px (JPG) để FB nhận được
  files.forEach((f, i) => { const heic = /heic|heif/i.test(f.mimeType || '') || /\.hei[cf]$/i.test(f.name || '');
    const url = heic && f.thumbnailLink ? f.thumbnailLink.replace(/=s\d+$/, '=s2048')
      : `https://www.googleapis.com/drive/v3/files/${f.id}?alt=media&supportsAllDrives=true`;
    out.push({ json: { ...meta, fileId: f.id, url, idx: i + 1, total: files.length } }); });
});
return out;

const by = {};
// Bài nào folder không có ảnh (video, thư mục con, trống) cũng phải ghi "Lỗi gói 0/0 ảnh"
for (const it of $('Có bài?').all()) { const k = it.json.row; by[k] = { row: k, code: it.json.code, note: it.json.note || '', total: 0, saved: 0 }; }
for (const it of $('Tách từng ảnh').all()) { const k = it.json.row; by[k] = by[k] || { row: k, code: it.json.code, note: it.json.note || '', saved: 0 }; by[k].total = it.json.total; }
for (const it of $input.all()) { const k = it.json.row; if (by[k]) by[k].saved++; }
// Ghi kết quả vào cột J (Ghi chú) của chính dòng Lịch SM — cấp 3 đọc "Gói sẵn" là có thư mục anh-dang-bai/Kxxx
const tag = b => (b.saved > 0 && b.saved === b.total ? 'Gói sẵn' : 'Lỗi gói') + ` ${b.saved}/${b.total} ảnh`;
const data = Object.values(by).map(b => ({ range: `'Lịch SM'!J${b.row}`, values: [[(b.note ? b.note + ' · ' : '') + tag(b)]] }));
return [{ json: { data, n: Object.keys(by).length } }];
